class VersionedKV:
    def __init__(self):
        self._working = {}
        self._history = []  # _history[i] is snapshot for version i + 1

    def set(self, key, value):
        self._working[key] = value

    def delete(self, key):
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key):
        return key in self._working

    def commit(self):
        self._history.append(dict(self._working))
        return len(self._history)

    def get_at(self, key, version):
        if not isinstance(version, int) or isinstance(version, bool) \
                or not 1 <= version <= len(self._history):
            raise ValueError(f"invalid version: {version!r}")
        snapshot = self._history[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version):
        if not isinstance(version, int) or isinstance(version, bool) \
                or not 0 <= version <= len(self._history):
            raise ValueError(f"invalid version: {version!r}")
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._history[version - 1])

    def latest(self):
        return len(self._history)

class UndoStack:
    def __init__(self):
        self._items = []
        self._history = []

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append(("push", x))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        x = self._items.pop()
        self._history.append(("pop", x))
        return x

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, x = self._history.pop()
        if op == "push":
            self._items.pop()
        else:
            self._items.append(x)

    def __len__(self) -> int:
        return len(self._items)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    counts = {}
    for value in items:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1

    # (value, count) pairs in first-occurrence order
    remaining = list(counts.items())
    result = []

    while len(result) < k and remaining:
        best_i = 0
        best_count = remaining[0][1]
        i = 1
        while i < len(remaining):
            current = remaining[i][1]
            if current > best_count:
                best_count = current
                best_i = i
            i += 1
        result.append(remaining.pop(best_i))

    return result

from collections import deque


def count_stable_windows(readings: list[int], tol: int) -> int:
    a = readings
    min_q = deque()  # indices with increasing values (front = window minimum)
    max_q = deque()  # indices with decreasing values (front = window maximum)
    left = 0
    total = 0
    for right in range(len(a)):
        x = a[right]
        while min_q and a[min_q[-1]] >= x:
            min_q.pop()
        min_q.append(right)
        while max_q and a[max_q[-1]] <= x:
            max_q.pop()
        max_q.append(right)
        while a[max_q[0]] - a[min_q[0]] > tol:
            left += 1
            if min_q[0] < left:
                min_q.popleft()
            if max_q[0] < left:
                max_q.popleft()
        total += right - left + 1
    return total

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

