import itertools


class TaskScheduler:
    """Priority queue of unique task ids with reprioritization/cancellation.

    Uses a lazy-deletion heap: entries are (-priority, submission_order, task_id),
    so higher priority wins and ties break by original submission order.
    Stale heap entries (from reprioritize/cancel/resubmit) are discarded
    when they reach the top, giving O(log n) amortized per operation.
    """

    def __init__(self):
        self._heap = []                 # [(-priority, order, task_id), ...]
        self._active = {}               # task_id -> (priority, order)
        self._counter = itertools.count()

    def __len__(self):
        return len(self._active)

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task {task_id!r} is already active")
        order = next(self._counter)
        self._active[task_id] = (priority, order)
        heapq.heappush(self._heap, (-priority, order, task_id))

    def reprioritize(self, task_id, priority):
        current = self._active.get(task_id)
        if current is None:
            raise KeyError(task_id)
        order = current[1]              # keep original FIFO position
        self._active[task_id] = (priority, order)
        heapq.heappush(self._heap, (-priority, order, task_id))

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]

    def priority_of(self, task_id):
        current = self._active.get(task_id)
        if current is None:
            raise KeyError(task_id)
        return current[0]

    def _purge_top(self):
        heap, active = self._heap, self._active
        while heap:
            neg_priority, order, task_id = heap[0]
            if active.get(task_id) == (-neg_priority, order):
                return
            heapq.heappop(heap)

    def peek(self):
        self._purge_top()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def pop(self):
        self._purge_top()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, task_id = heapq.heappop(self._heap)
        del self._active[task_id]
        return task_id

