def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("path contains an empty segment")

    def is_int_literal(text):
        digits = text[1:] if text.startswith("-") else text
        return digits != "" and digits.strip("0123456789") == ""

    def descend(node, parts):
        if not parts:
            return node
        segment = parts[0]
        remaining = parts[1:]
        if isinstance(node, dict):
            if segment not in node:
                raise KeyError(segment)
            return descend(node[segment], remaining)
        if isinstance(node, list):
            if not is_int_literal(segment):
                raise ValueError("invalid index: " + segment)
            index = int(segment)
            if index >= len(node) or index < -len(node):
                raise IndexError(segment)
            return descend(node[index], remaining)
        raise TypeError("cannot descend into " + type(node).__name__)

    return descend(data, segments)

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(data)

    # prev[i]  = previous index with same value (or -1)
    # prev2[i] = index before prev[i] with same value (or -1)
    prev = [-1] * n
    prev2 = [-1] * n
    last = {}
    for i, v in enumerate(data):
        entry = last.get(v)
        if entry is None:
            last[v] = (i, -1)
        else:
            p1, p2 = entry
            prev[i] = p1
            prev2[i] = p2
            last[v] = (i, p1)

    # A value with >= 2 occurrences in [l, r) is counted exactly once via its
    # second occurrence i inside the range: prev[i] >= l and prev2[i] < l.
    # Sweep l from n down to 0, maintaining those positions in a Fenwick tree.
    add_at = [[] for _ in range(n)]   # positions with prev[i] == l
    rem_at = [[] for _ in range(n)]   # positions with prev2[i] == l
    for i in range(n):
        p = prev[i]
        if p >= 0:
            add_at[p].append(i)
            q = prev2[i]
            if q >= 0:
                rem_at[q].append(i)

    qbyl = [[] for _ in range(n + 1)]
    for idx, (l, r) in enumerate(queries):
        qbyl[l].append((r, idx))

    ans = [0] * len(queries)
    bit = [0] * (n + 1)
    nn = n

    for l in range(n, -1, -1):
        if l < n:
            for i in add_at[l]:
                j = i + 1
                while j <= nn:
                    bit[j] += 1
                    j += j & -j
            for i in rem_at[l]:
                j = i + 1
                while j <= nn:
                    bit[j] -= 1
                    j += j & -j
        for r, idx in qbyl[l]:
            s = 0
            j = r
            while j:
                s += bit[j]
                j &= j - 1
            j = l
            while j:
                s -= bit[j]
                j &= j - 1
            ans[idx] = s

    return ans

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []
    operators = ("+", "-", "*", "/")

    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i} must be a string")

        if tok in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(
                        f"division by zero at token {i}")
                quotient = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    quotient = -quotient
                stack.append(quotient)
        else:
            digits = tok
            if digits[:1] in ("+", "-"):
                digits = digits[1:]
            if not digits or not all("0" <= c <= "9" for c in digits):
                raise ValueError(f"unknown token {i}: {tok!r}")
            stack.append(int(tok))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    NAME_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_"
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            p = i
            i += 1
            start = i
            while i < n and template[i] in NAME_CHARS:
                i += 1
            name = template[start:i]
            if i >= n:
                raise ValueError("unclosed placeholder at position %d" % p)
            if template[i] != "}":
                raise ValueError("invalid placeholder at position %d" % p)
            if not name:
                raise ValueError("empty placeholder at position %d" % p)
            i += 1
            out.append(str(context[name]))
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
                continue
            raise ValueError("stray '}' at position %d" % i)
        else:
            out.append(ch)
            i += 1
    return "".join(out)

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    from collections import defaultdict

    delta = defaultdict(int)
    for s, e in intervals:
        delta[s] += 1
        delta[e] -= 1

    max_load = 0
    earliest_t = 0
    load = 0
    for t in sorted(delta):
        load += delta[t]
        if load > max_load:
            max_load = load
            earliest_t = t

    return (max_load, earliest_t)

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    max_delete_end = 0
    for i, (start, delete, insert) in enumerate(ordered):
        if i > 0 and start == ordered[i - 1][0]:
            raise ValueError("conflicting hunks")
        if delete > 0:
            if start < max_delete_end:
                raise ValueError("conflicting hunks")
            max_delete_end = max(max_delete_end, start + delete)
    n = len(lines)
    for start, delete, insert in ordered:
        if start < 0 or start + delete > n:
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

def min_insertions(s, allowed):
    allowed = set(allowed)
    n = len(s)
    if n < 2:
        return 0

    INF = float('inf')
    # dp[i][j] = minimum insertions needed to make s[i..j] a palindrome
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                best = INF
                # Insert a copy of s[i] after position j (must be allowed)
                if s[i] in allowed:
                    best = dp[i + 1][j] + 1
                # Insert a copy of s[j] before position i (must be allowed)
                if s[j] in allowed and dp[i][j - 1] + 1 < best:
                    best = dp[i][j - 1] + 1
                dp[i][j] = best

    result = dp[0][n - 1]
    return -1 if result == INF else result

import math

def vector_norm(v: list[float]) -> float:
    if any(not math.isfinite(x) for x in v):
        raise ValueError("all vector entries must be finite")
    return float(math.hypot(*v))

