class IntervalSet:
    """A set of integers stored as normalized half-open intervals [lo, hi)."""

    __slots__ = ("_iv",)

    def __init__(self):
        # Sorted list of (lo, hi) tuples, pairwise disjoint and non-adjacent.
        self._iv = []

    @staticmethod
    def _validate(lo, hi):
        if lo >= hi:
            raise ValueError(f"expected lo < hi, got lo={lo}, hi={hi}")

    def add(self, lo, hi):
        self._validate(lo, hi)
        iv = self._iv
        i = bisect.bisect_left(iv, (lo, hi))
        # The interval just before i may overlap or touch [lo, hi).
        if i and iv[i - 1][1] >= lo:
            i -= 1
        nlo, nhi = lo, hi
        j = i
        # Merge every interval that overlaps or touches (a == hi counts).
        while j < len(iv) and iv[j][0] <= hi:
            a, b = iv[j]
            if a < nlo:
                nlo = a
            if b > nhi:
                nhi = b
            j += 1
        iv[i:j] = [(nlo, nhi)]

    def remove(self, lo, hi):
        self._validate(lo, hi)
        iv = self._iv
        i = bisect.bisect_left(iv, (lo, hi))
        # The interval just before i may reach into [lo, hi).
        if i and iv[i - 1][1] > lo:
            i -= 1
        keep = []
        j = i
        # Only strict overlaps are affected; touching intervals are untouched.
        while j < len(iv) and iv[j][0] < hi:
            a, b = iv[j]
            if a < lo:
                keep.append((a, lo))
            if b > hi:
                keep.append((hi, b))
            j += 1
        iv[i:j] = keep

    def contains(self, x):
        iv = self._iv
        # Last interval whose lo <= x.
        i = bisect.bisect_right(iv, (x, float("inf"))) - 1
        return i >= 0 and iv[i][0] <= x < iv[i][1]

    def total(self):
        return sum(b - a for a, b in self._iv)

    def intervals(self):
        return list(self._iv)

    def gaps(self, lo, hi):
        self._validate(lo, hi)
        res = []
        cur = lo
        for a, b in self._iv:
            if b <= lo:
                continue
            if a >= hi:
                break
            if a > cur:
                res.append((cur, a))
            if b > cur:
                cur = b
            if cur >= hi:
                return res
        if cur < hi:
            res.append((cur, hi))
        return res

import functools

def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    return wrapper

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")

    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")

    W = sum(weights)
    if len(values) == 0 or W <= 0:
        raise ValueError("total weight must be positive")

    threshold = W / 2 - 1e-9
    cumulative = 0.0
    for value, weight in sorted(zip(values, weights), key=lambda p: p[0]):
        cumulative += weight
        if cumulative >= threshold:
            return value

def longest_spaced_repeat(s, gap):
    n = len(s)
    # Need p + L + gap <= q and q + L <= n, so 2L + gap <= n.
    max_l = (n - gap) // 2
    if max_l <= 0:
        return 0

    def ok(L):
        # Earliest start index of each length-L substring seen so far.
        earliest = {}
        need = L + gap  # required minimum q - p
        for q in range(n - L + 1):
            sub = s[q:q + L]
            p = earliest.get(sub)
            if p is None:
                earliest[sub] = q
            elif q - p >= need:
                return True
        return False

    # Feasibility is monotonic in L: a valid repeat of length L
    # yields valid repeats of every smaller positive length.
    lo, hi, ans = 1, max_l, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if ok(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("no balanced replacement exists")

    half = n // 2
    opens_needed = half - s.count('(')
    question_marks = s.count('?')

    if opens_needed < 0 or opens_needed > question_marks:
        raise ValueError("no balanced replacement exists")

    # Assigning '(' to the earliest possible '?' positions maximizes the
    # running balance at every prefix among all assignments with the correct
    # total count, so it is both lexicographically smallest and valid
    # whenever any valid assignment exists.
    result = []
    balance = 0
    remaining_opens = opens_needed

    for ch in s:
        if ch == '(':
            result.append('(')
            balance += 1
        elif ch == ')':
            result.append(')')
            balance -= 1
        else:
            if remaining_opens > 0:
                result.append('(')
                balance += 1
                remaining_opens -= 1
            else:
                result.append(')')
                balance -= 1

        if balance < 0:
            raise ValueError("no balanced replacement exists")

    if balance != 0:
        raise ValueError("no balanced replacement exists")

    return ''.join(result)

import re

_AMOUNT_RE = re.compile(r"^[0-9]+(\.[0-9]{1,2})?$")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str) or not _AMOUNT_RE.match(amount):
            raise ValueError("invalid amount: %r" % (amount,))
        if "." in amount:
            whole, frac = amount.split(".", 1)
            cents = int(whole) * 100 + int(frac.ljust(2, "0"))
        else:
            cents = int(amount) * 100
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

class Leaderboard:
    def __init__(self):
        # player -> (best_score, sequence_number_of_improving_submission)
        self._best = {}
        self._seq = 0

    def submit(self, player, score) -> bool:
        current = self._best.get(player)
        if current is not None and score <= current[0]:
            return False
        self._best[player] = (score, self._seq)
        self._seq += 1
        return True

    def best(self, player) -> int:
        return self._best[player][0]

    def rank(self, player) -> int:
        player_best = self._best[player][0]
        return 1 + sum(1 for best, _ in self._best.values() if best > player_best)

    def top(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        ordered = sorted(
            self._best.items(),
            key=lambda item: (-item[1][0], item[1][1]),
        )
        return [(player, best) for player, (best, _) in ordered[:k]]

    def player_count(self) -> int:
        return len(self._best)

from collections import deque


def round_robin(iterables):
    iterators = deque(iter(it) for it in iterables)
    while iterators:
        it = iterators.popleft()
        try:
            value = next(it)
        except StopIteration:
            continue
        yield value
        iterators.append(it)

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        self._data = OrderedDict()  # key -> (value, stored_time, ttl)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        dead = [
            key
            for key, (_, stored_time, ttl) in self._data.items()
            if ttl is not None and now >= stored_time + ttl
        ]
        for key in dead:
            del self._data[key]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number or None")
        self._purge(now)
        if key in self._data:
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
                self._evictions += 1
            self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._data)

from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    N = R * C

    labels = [0] * N
    blocked = [False] * N
    counts = {}

    for r, row in enumerate(grid):
        base = r * C
        for col, x in enumerate(row):
            i = base + col
            if x == -1:
                blocked[i] = True
            else:
                labels[i] = x
                counts[x] = counts.get(x, 0) + 1

    if blocked[0] or blocked[-1]:
        return -1

    def bfs(start):
        dist = [-1] * N
        dist[start] = 0
        q = deque([start])
        while q:
            i = q.popleft()
            nd = dist[i] + 1
            r = i // C
            col = i - r * C

            if r > 0:
                j = i - C
                if not blocked[j] and dist[j] < 0:
                    dist[j] = nd
                    q.append(j)
            if r + 1 < R:
                j = i + C
                if not blocked[j] and dist[j] < 0:
                    dist[j] = nd
                    q.append(j)
            if col > 0:
                j = i - 1
                if not blocked[j] and dist[j] < 0:
                    dist[j] = nd
                    q.append(j)
            if col + 1 < C:
                j = i + 1
                if not blocked[j] and dist[j] < 0:
                    dist[j] = nd
                    q.append(j)
        return dist

    ds = bfs(0)
    dt = bfs(N - 1)

    INF = 10**18
    ans = ds[-1] if ds[-1] >= 0 else INF

    # For each label: best/second-best ds among cells reachable from start,
    # and best/second-best dt among cells that can reach the target.
    groups = {}

    for i in range(N):
        if blocked[i]:
            continue
        lab = labels[i]
        if counts[lab] < 2:
            continue

        d0 = ds[i]
        d1 = dt[i]
        if d0 < 0 and d1 < 0:
            continue

        st = groups.get(lab)
        if st is None:
            st = [INF, -1, INF, -1, INF, -1, INF, -1]
            groups[lab] = st

        if d0 >= 0:
            if d0 < st[0]:
                st[2] = st[0]
                st[3] = st[1]
                st[0] = d0
                st[1] = i
            elif d0 < st[2]:
                st[2] = d0
                st[3] = i

        if d1 >= 0:
            if d1 < st[4]:
                st[6] = st[4]
                st[7] = st[5]
                st[4] = d1
                st[5] = i
            elif d1 < st[6]:
                st[6] = d1
                st[7] = i

    for b0v, b0i, s0v, s0i, b1v, b1i, s1v, s1i in groups.values():
        if b0i < 0 or b1i < 0:
            continue

        if b0i != b1i:
            cand = b0v + b1v + c
        else:
            cand = INF
            if s0i >= 0:
                cand = s0v + b1v + c
            if s1i >= 0:
                tmp = b0v + s1v + c
                if tmp < cand:
                    cand = tmp

        if cand < ans:
            ans = cand

    return -1 if ans == INF else ans

def best_circular_selection(values, k):
    if k == 0:
        return 0
    if k < 0:
        raise ValueError("no valid selection")

    n = len(values)
    if n == 0:
        raise ValueError("no valid selection")
    if n == 1:
        if k == 1:
            return int(values[0])
        raise ValueError("no valid selection")
    if k > n // 2:
        raise ValueError("no valid selection")

    NEG = -10**18

    def path_best(arr, t):
        not_last = [NEG] * (t + 1)
        last = [NEG] * (t + 1)
        not_last[0] = 0

        for x in arr:
            for j in range(t, 0, -1):
                prev = not_last[j - 1]
                cand = prev + x if prev != NEG else NEG
                a = not_last[j]
                b = last[j]
                not_last[j] = a if a >= b else b
                last[j] = cand

        ans = not_last[t]
        if last[t] > ans:
            ans = last[t]
        return ans

    best = path_best(values[1:], k)

    rest = path_best(values[2:-1], k - 1)
    if rest != NEG:
        cand = values[0] + rest
        if cand > best:
            best = cand

    if best == NEG:
        raise ValueError("no valid selection")
    return int(best)

def kth_root_floor(n: int, k: int) -> int:
    if n < 0:
        raise ValueError("n must be nonnegative")
    if k < 1:
        raise ValueError("k must be at least 1")
    if k == 1 or n < 2:
        return n

    def bounded_pow(base: int, exp: int, cap: int) -> int:
        # Return base**exp, but stop early / cap intermediates once the
        # value is known to exceed cap (keeps huge exponents cheap).
        result = 1
        b = base
        e = exp
        while e:
            if e & 1:
                result *= b
                if result > cap:
                    return result
            e >>= 1
            if e:
                b *= b
                if b > cap:
                    b = cap + 1
        return result

    # hi is an exclusive upper bound: hi**k = 2**(k*ceil(bitlen/k)) >= 2**bitlen > n.
    lo = 1
    hi = 1 << ((n.bit_length() + k - 1) // k)
    while lo + 1 < hi:
        mid = (lo + hi) >> 1
        if bounded_pow(mid, k, n) <= n:
            lo = mid
        else:
            hi = mid
    return lo

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str, got %s" % type(text).__name__)
    if len(text) == 0 or len(text.strip()) == 0:
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    total = 0
    i = 0
    n = len(text)
    last_order = -1

    while i < n:
        value = 0
        digit_count = 0
        while i < n and "0" <= text[i] <= "9":
            value = value * 10 + (ord(text[i]) - 48)
            i += 1
            digit_count += 1
        if digit_count == 0:
            raise ValueError("malformed duration: expected digits")
        if i >= n:
            raise ValueError("malformed duration: missing unit letter")
        unit = text[i]
        if unit not in units:
            raise ValueError("malformed duration: invalid unit")
        order, multiplier = units[unit]
        if order <= last_order:
            raise ValueError("malformed duration: components out of order or repeated")
        last_order = order
        total += value * multiplier
        i += 1

    return total

import unicodedata

_COMBINING_CATEGORIES = frozenset(("Mn", "Mc", "Me"))


def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")

    units = 0
    end = 0
    for i, ch in enumerate(s):
        if unicodedata.category(ch) in _COMBINING_CATEGORIES and units > 0:
            # Combining mark: joins the current unit, adding zero width.
            pass
        else:
            # Non-combining code point, or a leading combining mark with
            # nothing to attach to: starts a new unit of width 1.
            units += 1
            if units > width:
                break
        end = i + 1
    return s[:end]

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    iterators = [iter(nested)]
    depths = [0]

    while iterators:
        current = iterators[-1]
        depth = depths[-1]
        advanced = False
        for item in current:
            advanced = True
            if isinstance(item, list) and depth < max_depth:
                iterators.append(iter(item))
                depths.append(depth + 1)
                break
            result.append(item)
        if not advanced:
            iterators.pop()
            depths.pop()

    return result

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._entry = {}
        self._clock = 0
        self._total = 0

    def add(self, item):
        if item not in self._counts:
            self._entry[item] = self._clock
            self._clock += 1
            self._counts[item] = 1
        else:
            self._counts[item] += 1
        self._total += 1
        return self._counts[item]

    def discard(self, item):
        current = self._counts.get(item)
        if not current:
            return False
        if current == 1:
            del self._counts[item]
            del self._entry[item]
        else:
            self._counts[item] = current - 1
        self._total -= 1
        return True

    def count(self, item):
        return self._counts.get(item, 0)

    def __len__(self):
        return self._total

    def distinct(self):
        return len(self._counts)

    def most_common(self, k):
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        ordered = sorted(
            self._counts,
            key=lambda item: (-self._counts[item], self._entry[item]),
        )
        return [(item, self._counts[item]) for item in ordered[:k]]

def rank_scores(scores: list) -> list[int]:
    for s in scores:
        if s != s:  # NaN check
            raise ValueError("NaN scores are not allowed")
    distinct = sorted(set(scores), reverse=True)
    rank_of = {value: i + 1 for i, value in enumerate(distinct)}
    return [rank_of[s] for s in scores]

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    for bound in (low, high):
        if isinstance(bound, bool) or not isinstance(bound, (int, float)):
            raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("invalid value at index {}".format(i))
    result = []
    for item in values:
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)
    return result

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError("row {} must be a tuple of exactly 3 elements".format(i))
        category, amount, refunded = row
        if not isinstance(category, str) or category == "":
            raise ValueError("row {} has an invalid category".format(i))
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError("row {} has an invalid amount".format(i))
        if amount < 0:
            raise ValueError("row {} has a negative amount".format(i))
        if not isinstance(refunded, bool):
            raise TypeError("row {} has an invalid refunded flag".format(i))
        value = float(amount)
        summary = result.get(category)
        if summary is None:
            result[category] = {
                "count": 1,
                "gross": value,
                "net": 0.0 if refunded else value,
                "largest": value,
            }
        else:
            summary["count"] += 1
            summary["gross"] += value
            if not refunded:
                summary["net"] += value
            if value > summary["largest"]:
                summary["largest"] = value
    return result

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            if d not in graph[pkg]:
                graph[pkg].append(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be a positive integer")
    n = len(jobs)
    if n == 0:
        return 0

    # Union-find over time slots. parent[s] links s to the latest slot < s
    # that may still have free capacity once s is completely full.
    # Slots beyond n are never needed since at most n jobs can be placed.
    parent = list(range(n + 1))
    used = [0] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    for d, p in sorted(jobs, key=lambda j: j[1], reverse=True):
        s = find(d if d <= n else n)
        if s:
            total += p
            u = used[s] + 1
            used[s] = u
            if u == cap:
                parent[s] = find(s - 1)
    return total
